def oxford_join_or(items):
    if len(items) == 0:
        return ''
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return items[0] + ' or ' + items[1]
    return ', '.join(items[:-1]) + ', or ' + items[-1]

def oxford_join_custom(items, conj):
    if len(items) == 0:
        return ''
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return items[0] + ' ' + conj + ' ' + items[1]
    return ', '.join(items[:-1]) + ', ' + conj + ' ' + items[-1]

def oxford_join_semicolon(items):
    if len(items) == 0:
        return ''
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return items[0] + ' and ' + items[1]
    sep = ';' if any(',' in item for item in items) else ','
    return (sep + ' ').join(items[:-1]) + sep + ' and ' + items[-1]

def oxford_join_numbers(numbers):
    items = [str(n) for n in numbers]
    if len(items) == 0:
        return ''
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return items[0] + ' and ' + items[1]
    return ', '.join(items[:-1]) + ', and ' + items[-1]

def oxford_join_empty_word(items, empty_word):
    if len(items) == 0:
        return empty_word
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return items[0] + ' and ' + items[1]
    return ', '.join(items[:-1]) + ', and ' + items[-1]

def wrap_double_quotes(s):
    escaped = s.replace('"', '\\"')
    return '"' + escaped + '"'

def wrap_single_quotes(s):
    escaped = s.replace("'", "\\'")
    return "'" + escaped + "'"

def quote_if_needed(s):
    if ' ' in s or ',' in s:
        return '"' + s + '"'
    return s

def csv_quote(s):
    if ',' in s or '"' in s or '\n' in s:
        return '"' + s.replace('"', '""') + '"'
    return s

def block_quote(text):
    lines = text.split('\n')
    return '\n'.join('> ' + line for line in lines)

def banner_line(word, width, fill):
    padded = ' ' + word + ' '
    if width <= len(padded):
        return padded
    return padded.center(width, fill)
